// Z-API Webhook Parser - Normaliza todas as mensagens recebidas
const raw = $input.first().json;

// Z-API envia diferentes tipos de evento
const isMessage = raw.isStatusReply === false || raw.type === 'ReceivedCallback';
const isGroupMsg = raw.isGroup || false;

// Ignorar mensagens de grupo e status
if (isGroupMsg || !raw.phone) {
  return [{ json: { skip: true, reason: 'group_or_no_phone' } }];
}

// Extrair dados da mensagem
const phone = raw.phone || raw.chatId?.replace('@c.us','') || '';
const senderName = raw.senderName || raw.chatName || raw.pushName || '';
const messageId = raw.messageId || raw.id?.id || '';

// Tipo de mensagem
let messageType = 'text';
let messageContent = '';
let mediaUrl = '';

if (raw.text?.message) {
  messageType = 'text';
  messageContent = raw.text.message;
} else if (raw.image) {
  messageType = 'image';
  messageContent = raw.image.caption || '[Imagem recebida]';
  mediaUrl = raw.image.imageUrl || '';
} else if (raw.audio) {
  messageType = 'audio';
  messageContent = '[Audio recebido - transcricao pendente]';
  mediaUrl = raw.audio.audioUrl || '';
} else if (raw.document) {
  messageType = 'document';
  messageContent = raw.document.fileName || '[Documento recebido]';
  mediaUrl = raw.document.documentUrl || '';
} else if (raw.sticker) {
  messageType = 'sticker';
  messageContent = '[Sticker]';
} else if (raw.listResponseMessage) {
  messageType = 'list_response';
  messageContent = raw.listResponseMessage.title || raw.listResponseMessage.description || '';
} else if (raw.buttonsResponseMessage) {
  messageType = 'button_response';
  messageContent = raw.buttonsResponseMessage.selectedButtonId || '';
} else {
  messageContent = raw.body || raw.message || JSON.stringify(raw).substring(0, 200);
}

return [{
  json: {
    phone: phone,
    sender_name: senderName,
    message_id: messageId,
    message_type: messageType,
    message_content: messageContent,
    media_url: mediaUrl,
    timestamp: raw.momment || new Date().toISOString(),
    raw_event: raw.type || 'message',
    is_from_me: raw.fromMe || false
  }
}];

// Check if lead exists or is new
const existingLeads = $('Find Lead by Phone').all();
const message = $('Valid Incoming Message?').first().json;

const isNewLead = existingLeads.length === 0 || !existingLeads[0].json.lead_id;

if (isNewLead) {
  return [{
    json: {
      ...message,
      is_new_lead: true,
      lead_id: '',
      lead_name: message.sender_name,
      lead_stage: 'new_lead',
      lead_score: 0
    }
  }];
}

const lead = existingLeads[0].json;
return [{
  json: {
    ...message,
    is_new_lead: false,
    lead_id: lead.lead_id,
    lead_name: lead.name || message.sender_name,
    lead_stage: lead.stage,
    lead_score: lead.score || 0,
    lead_email: lead.email || '',
    lead_source: lead.source || 'whatsapp',
    lead_nationality: lead.nationality || '',
    lead_english_level: lead.english_level || '',
    lead_preferred_date: lead.preferred_date || ''
  }
}];

// Z-API Send Message Router
// Supports: text, image, document, buttons, list
const input = $input.first().json;
const phone = input.phone;
const instanceId = $env.ZAPI_INSTANCE_ID;
const token = $env.ZAPI_TOKEN;
const baseUrl = `https://api.z-api.io/instances/${instanceId}/token/${token}`;

let endpoint = '';
let body = {};

switch (input.type || 'text') {
  case 'text':
    endpoint = '/send-text';
    body = {
      phone: phone,
      message: input.message
    };
    break;

  case 'image':
    endpoint = '/send-image';
    body = {
      phone: phone,
      image: input.media_url,
      caption: input.message || ''
    };
    break;

  case 'document':
    endpoint = '/send-document/pdf';
    body = {
      phone: phone,
      document: input.media_url,
      fileName: input.file_name || 'documento.pdf',
      caption: input.message || ''
    };
    break;

  case 'buttons':
    endpoint = '/send-button-list';
    body = {
      phone: phone,
      message: input.message,
      buttonList: {
        buttons: (input.buttons || []).map(b => ({
          id: b.id,
          label: b.label
        }))
      }
    };
    break;

  case 'list':
    endpoint = '/send-option-list';
    body = {
      phone: phone,
      optionList: {
        title: input.list_title || 'Opcoes',
        message: input.message,
        footer: input.footer || 'BR Academy',
        buttonLabel: input.button_label || 'Ver opcoes',
        options: input.options || []
      }
    };
    break;

  default:
    endpoint = '/send-text';
    body = { phone: phone, message: input.message };
}

return [{
  json: {
    url: baseUrl + endpoint,
    body: body,
    phone: phone,
    type: input.type || 'text'
  }
}];
